def convolve_text(encoded, weights):
    width = len(weights)
    if len(encoded) < width:
        return np.array([], dtype=float)
    return np.array([
        np.sum(encoded[i:i + width] * weights)
        for i in range(len(encoded) - width + 1)
    ])

